#include <stdio.h>
#include <stdlib.h>

typedef struct { int *data; int size; int cap; } Heap;

void heap_init(Heap *h, int cap) {
    h->data = malloc(cap * sizeof(int)); h->size = 0; h->cap = cap;
}

void swap(int *a, int *b) { int t=*a; *a=*b; *b=t; }

void heap_push(Heap *h, int val) {
    int i = h->size++;
    h->data[i] = val;
    while (i > 0 && h->data[(i-1)/2] > h->data[i]) {
        swap(&h->data[i], &h->data[(i-1)/2]);
        i = (i-1)/2;
    }
}

int heap_pop(Heap *h) {
    int min = h->data[0];
    h->data[0] = h->data[--h->size];
    int i = 0;
    while (1) {
        int smallest = i;
        int l = 2*i+1, r = 2*i+2;
        if (l < h->size && h->data[l] < h->data[smallest]) smallest = l;
        if (r < h->size && h->data[r] < h->data[smallest]) smallest = r;
        if (smallest == i) break;
        swap(&h->data[i], &h->data[smallest]);
        i = smallest;
    }
    return min;
}

int main() {
    Heap h; heap_init(&h, 20);
    int vals[] = {5, 3, 8, 1, 9, 2};
    for (int i = 0; i < 6; i++) heap_push(&h, vals[i]);
    while (h.size > 0) printf("%d ", heap_pop(&h));
    printf("\n");
    free(h.data);
    return 0;
}
